    // Collect vertices of the outer boundary (CCW order)
    std::vector<Point2d> outer;
    auto he = fit->outer_ccb();
    if (he == nullptr) continue; // safety check
    auto start = he;
    do {
        const auto& p = he->source()->point();
        outer.emplace_back(p.x(), p.y());
        he = he->next();
    } while (he != start);

    // Build the polygon
    Polygon2d poly;
    for (const auto& pt : outer)
        poly.pushBack(pt);
    poly.updateBoundingBox();

    // Optionally handle holes (inner_ccb) – ignored for now
    result.push_back(std::move(poly));
}
